                start_row, start_col = r, c

    # Create a copy of the board
    next_board = [row[:] for row in board]

    # Perform the action
    for r in range(max(0, start_row-1), min(64, start_row+2)):
        for c in range(max(0, start_col-1), min(64, start_col+2)):
